package blockbranch.realistic;
import blockbranch.Blockbranch;
import blockbranch.cubic.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.*;

/** Actual open snow,soil,light/support behavior,immutable profiles and saved layer edits. */
public final class OpenSnowSmoke {
 private static final Map<DrainageNetwork,BlockPos> FIXTURE=Collections.synchronizedMap(new WeakHashMap<>()),SLOPE_FIXTURE=Collections.synchronizedMap(new WeakHashMap<>());
 public static BlockPos fixture(RealisticGenerator g,RandomState r){return FIXTURE.computeIfAbsent(g.drainage(r),d->{var p=blockbranch.realistic.SnowyPlainsFixtures.fixture(d,r.seed());return new BlockPos(p.x(),d.sample(p.x(),p.z()).height(),p.z());});}
 public static BlockPos fixture(RealisticGenerator g,RandomState r,boolean slopes){if(!slopes)return fixture(g,r);if(Boolean.getBoolean("blockbranch.terrainContourComparison"))return new BlockPos(-1332024,g.drainage(r).sample(-1332024,-1900024).height(),-1900024);return SLOPE_FIXTURE.computeIfAbsent(g.drainage(r),d->{var p=blockbranch.realistic.SnowySlopesFixtures.fixture(d,r.seed());return new BlockPos(p.x(),d.sample(p.x(),p.z()).height(),p.z());});}
 public static void restore(ServerLevel level,BlockPos bed){var base=((SparseColumn)level.getChunkAt(bed)).blockbranch$terrain().base();for(int y=0;y<=1;y++){var p=bed.above(y);level.setBlock(p,base.state(p.getX(),p.getY(),p.getZ()),3);}}
 public static void verify(ServerLevel level,RealisticGenerator g,boolean reload){verify(level,g,reload,false);}
 public static void verify(ServerLevel level,RealisticGenerator g,boolean reload,boolean slopes){var r=level.getChunkSource().randomState();var d=g.drainage(r);var bed=fixture(g,r,slopes);var root=bed.above();var home=((SparseColumn)level.getChunkAt(bed)).blockbranch$terrain().base();var natural=home.state(root.getX(),root.getY(),root.getZ());int savedLayers=Math.min(8,natural.getValue(SnowLayerBlock.LAYERS)+1);var saved=bed.below(8);if(reload){require(level.getBlockState(saved).is(Blocks.CLAY),"Saved open-snow bed edit");require(level.getBlockState(root).is(Blocks.SNOW)&&level.getBlockState(root).getValue(SnowLayerBlock.LAYERS)==savedLayers,"Saved native snow-layer edit");}restore(level,bed);var fence=level.getChunkSource().getLightEngine().waitForPendingTasks(bed.getX()>>4,bed.getZ()>>4);level.getServer().managedBlock(fence::isDone);fence.join();require(level.getBiome(bed).is(slopes?net.minecraft.world.level.biome.Biomes.SNOWY_SLOPES:net.minecraft.world.level.biome.Biomes.SNOWY_PLAINS),"Actual stored vanilla open-snow identity");if(slopes)require(level.getBlockState(bed).is(ScreeContent.LOOSE_SCREE)&&g.screeDepth(bed.getX(),bed.getZ(),r)>0,"Snowy slopes retain natural debris substrate");int snow=0;var layers=new HashSet<Integer>();
 for(int cz=(bed.getZ()>>4)-1;cz<=(bed.getZ()>>4)+1;cz++)for(int cx=(bed.getX()>>4)-1;cx<=(bed.getX()>>4)+1;cx++){var chunk=level.getChunk(cx,cz);var base=((SparseColumn)chunk).blockbranch$terrain().base();var tag=base.encode(level.palettedContainerFactory());var copy=TerrainProfile.decode(tag,level.palettedContainerFactory());var sections=new HashMap<Integer,net.minecraft.world.level.chunk.LevelChunkSection>();for(int v:base.canopy().encode()){int code=v&blockbranch.cubic.CanopyLayer.STATE_MASK;if(!SnowyTaiga.snow(code))continue;int key=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,x=cx*16+(key&15),z=cz*16+((key>>>4)&15),y=(key>>>8)+TerrainShape.FLOOR;var p=new BlockPos(x,y,z);var state=level.getBlockState(p);snow++;layers.add(state.getValue(SnowLayerBlock.LAYERS));require(state==copy.state(x,y,z)&&state==g.surfaceState(x,y,z,r)&&state==sections.computeIfAbsent(y>>4,copy::generate).getBlockState(x&15,y&15,z&15),"Native/profile/client snow materialization");require(state.canSurvive(level,p)&&base.randomTickSections().contains(y>>4),"Native supported ticking snow");require(d.sample(x,z).waterLevel()==DrainageNetwork.DRY&&y==d.sample(x,z).height()+1&&level.getFluidState(p).isEmpty(),"Grounded dry open snow preserves hydrology");var soil=level.getBlockState(p.below());if(soil.hasProperty(SnowyBlock.SNOWY))require(soil.getValue(SnowyBlock.SNOWY),"Native snow-covered soil state");}
  for(int z=0;z<16;z+=4)for(int x=0;x<16;x+=4){int wx=cx*16+x,wz=cz*16+z,h=d.sample(wx,wz).height();for(int y=h-3;y<=h+2;y++)require(level.getBlockState(new BlockPos(wx,y,wz))==g.surfaceState(wx,y,wz,r)&&copy.state(wx,y,wz)==g.surfaceState(wx,y,wz,r),"Native dry soil/cover agreement");for(var type:Heightmap.Types.values()){require(chunk.getHeight(type,x,z)+1==g.getBaseHeight(wx,wz,type,level,r),"All native open-snow heightmaps");for(var bounds:new net.minecraft.world.level.LevelHeightAccessor[]{net.minecraft.world.level.LevelHeightAccessor.create(h-2,3),net.minecraft.world.level.LevelHeightAccessor.create(h+1,2),net.minecraft.world.level.LevelHeightAccessor.create(h+3,2)}){var column=g.getBaseColumn(wx,wz,bounds,r);int expected=bounds.getMinY();for(int y=bounds.getMaxY();y>=bounds.getMinY();y--)if(type.isOpaque().test(column.getBlock(y))){expected=y+1;break;}require(g.getBaseHeight(wx,wz,type,bounds,r)==expected,"Clipped native snow heightmap");}}}
  var a=tag.getIntArray("canopy").orElseThrow();if(a.length>0){int first=base.canopy().encode()[0];a[0]=0;require(base.canopy().encode()[0]==first,"Immutable open-snow encoded snapshot");}
 }
 verifyBoundary(level,g,r,bed,slopes);
 require(snow>1000&&layers.size()>=2,"Actual coherent variable-depth snow field");require(Block.getDrops(natural,level,root,null,net.minecraft.world.entity.EntityTypes.PIG.create(level,net.minecraft.world.entity.EntitySpawnReason.COMMAND),new ItemStack(Items.IRON_SHOVEL)).stream().filter(s->s.is(Items.SNOWBALL)).mapToInt(ItemStack::getCount).sum()==natural.getValue(SnowLayerBlock.LAYERS),"Native snow harvest yields one snowball per layer with actual entity context");level.setBlock(bed,Blocks.AIR.defaultBlockState(),3);require(level.getBlockState(root).isAir(),"Native snow responds to support loss");restore(level,bed);
 var melt=bed.above(40);level.setBlock(melt.below(),Blocks.STONE.defaultBlockState(),3);var test=Blocks.SNOW.defaultBlockState().setValue(SnowLayerBlock.LAYERS,4);level.setBlock(melt,test,3);level.setBlock(melt.east(),Blocks.GLOWSTONE.defaultBlockState(),3);var light=level.getChunkSource().getLightEngine().waitForPendingTasks(melt.getX()>>4,melt.getZ()>>4);level.getServer().managedBlock(light::isDone);light.join();require(level.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,melt)>11,"Real snow melt-light witness");test.randomTick(level,melt,net.minecraft.util.RandomSource.create(1));require(level.getBlockState(melt).isAir(),"Native strong block-light snow melt");for(var p:List.of(melt,melt.below(),melt.east())){var base=((SparseColumn)level.getChunkAt(p)).blockbranch$terrain().base();level.setBlock(p,base.state(p.getX(),p.getY(),p.getZ()),3);}
 level.setBlock(root,natural.setValue(SnowLayerBlock.LAYERS,savedLayers),3);level.setBlock(saved,Blocks.CLAY.defaultBlockState(),2);var chunk=level.getChunkAt(bed);chunk.markUnsaved();var terrain=((SparseColumn)chunk).blockbranch$terrain();terrain.flush();terrain.evictOutside(-100,-90);require(level.getBlockState(root).getValue(SnowLayerBlock.LAYERS)==savedLayers&&level.getBlockState(saved).is(Blocks.CLAY),"Snow layer and bed edits survive lazy eviction");Blockbranch.LOGGER.info("OPEN_SNOW_NATIVE_PASS habitat={} mode={} bed={} snow={} layers={}",slopes?"snowy_slopes":"snowy_plains",reload?"RELOAD":"NEW",bed,snow,layers);
 }
 public static double[] camera(RealisticGenerator g,RandomState r,BlockPos bed,boolean elevated){return camera(g,r,bed,elevated,false);}
 public static double[] camera(RealisticGenerator g,RandomState r,BlockPos bed,boolean elevated,boolean slopes){if(slopes&&Boolean.getBoolean("blockbranch.terrainContourComparison"))return new double[]{-1332043.5,elevated?2638.625:g.drainage(r).sample(-1332044,-1900004).height()+1.625,-1900003.5,-135.,elevated?28.:8.};var d=g.drainage(r);var c=new ClimateField(r.seed());for(int radius:new int[]{28,36,44})for(int n=0;n<16;n++){double a=2.35+n*Math.PI/8;int x=bed.getX()+(int)Math.round(Math.cos(a)*radius),z=bed.getZ()+(int)Math.round(Math.sin(a)*radius),h=d.sample(x,z).height();if(!(slopes?SnowySlopes.contains(x,z,d,c):SnowyPlains.contains(x,z,d,c)))continue;boolean clear=true;for(int dz=slopes?-1:-2;dz<=(slopes?1:2);dz++)for(int dx=slopes?-1:-2;dx<=(slopes?1:2);dx++)for(int dy=slopes?3:2;dy<=4;dy++)if(!g.surfaceState(x+dx,h+dy,z+dz,r).isAir())clear=false;if(!clear)continue;var snow=g.surfaceState(x,h+1,z,r);double y=h+1+(snow.is(Blocks.SNOW)?snow.getValue(SnowLayerBlock.LAYERS)/8.0:0)+(elevated?44:0),yaw=Math.toDegrees(Math.atan2(-(bed.getX()-x),bed.getZ()-z));return new double[]{x+.5,y,z+.5,yaw,elevated?28:8};}throw new AssertionError("No natural open-snow camera");}
 private static void verifyBoundary(ServerLevel level,RealisticGenerator g,RandomState r,BlockPos bed,boolean slopes){var d=g.drainage(r);var climate=new ClimateField(r.seed());var resolver=g.getBiomeSource().createUncachedResolver(r);for(int axis=0;axis<2;axis++)for(int delta=-8192;delta<=8192;delta+=16){int cx=(bed.getX()+(axis==0?delta:0))>>4,cz=(bed.getZ()+(axis==1?delta:0))>>4,n=0;for(int z=0;z<4;z++)for(int x=0;x<4;x++)if(slopes?SnowySlopes.contains(cx*16+x*4,cz*16+z*4,d,climate):SnowyPlains.contains(cx*16+x*4,cz*16+z*4,d,climate))n++;if(n==0||n==16)continue;var chunk=level.getChunk(cx,cz);var base=((SparseColumn)chunk).blockbranch$terrain().base();var copy=TerrainProfile.decode(base.encode(level.palettedContainerFactory()),level.palettedContainerFactory());for(int z=0;z<4;z++)for(int x=0;x<4;x++){int qx=cx*4+x,qz=cz*4+z;var expected=resolver.getNoiseBiome(qx,0,qz);for(int y:new int[]{-3000,0,bed.getY()>>2,2000})require(chunk.getNoiseBiome(qx,y,qz).equals(expected)&&copy.biomes().get(x,y&3,z).equals(expected),"Mixed open-snow source/stored/decoded biome identity at all heights");}for(int z=0;z<16;z++)for(int x=0;x<20;x++){int wx=cx*16+x,wz=cz*16+z,h=d.sample(wx,wz).height();var neighbor=level.getChunk(wx>>4,wz>>4);for(int y=h-2;y<=h+2;y++)require(neighbor.getBlockState(new BlockPos(wx,y,wz))==g.surfaceState(wx,y,wz,r),"Native snow boundary substrate/fluid/material continuity across chunk seam");}Blockbranch.LOGGER.info("OPEN_SNOW_BOUNDARY_PASS habitat={} chunk={} selectedQuartCells={}",slopes?"snowy_slopes":"snowy_plains",chunk.getPos(),n);return;}throw new AssertionError("No mixed open-snow boundary near fixture");}
 private static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
 private OpenSnowSmoke(){}
}
